+ * This uses a restricted Function constructor to prevent access to global scope.
+ */
+export function evalInContext(code: string, context: Record<string, any>): any {
+    const keys = Object.keys(context);
+    const values = Object.values(context);
+    
+    // We wrap the execution to prevent access to 'window', 'document', and 'global'
+    // by shadowing them with null values in the function arguments.
+    const shadowKeys = ['window', 'document', 'global', 'process', 'require'];
+    const shadowValues = shadowKeys.map(() => null);
+
+    try {
+        const evaluator = new Function(...shadowKeys, ...keys, `"use strict"; return (${code});`);
+        return evaluator(...shadowValues, ...values);
+    } catch (e) {
+        return `Error: ${e.message}`;
+    }
